head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > checkboxRadioOnCellClick]<br/>inputType='checkbox','radio' 일때 읽기전용(readonly) 상태인 Body Cell 클릭 시 oncellclick 이벤트가 발생하게 설정합니다.",
    "validation" : [
        "true 설정 시 inputType='checkbox','radio' 일때 읽기전용(readonly) 상태인 Body Cell 클릭 시 oncellclick 이벤트가 발생합니다.",
        "true 설정 시 CheckBox/Radio 영역이 아닌 Cell 영역(td 요소)에만 적용됩니다.",
        "true 설정 시 Body Cell 의 상태값을 변경하지 않습니다.",
        "false (기본값) 설정 시 읽기전용(readonly) 상태인 Body Cell 클릭 시 oncellclick 이벤트가 발생하지 않습니다.",
        "비활성화(disabled) 상태인 Body Cell 에선 동작하지 않습니다.",
        "미설정 시 기본값 false 로 동작합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 라벨 생성
    $c.gcm.createLabel('label="Row 0: 일반 / Row 1: readOnly / Row 2: disabled (chk Column = checkbox, rdo Column = radio)"', '', 'label1');

    // dataList 생성 (3 row, 컬럼: chk, rdo)
    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    let strDataList = '<w2:dataList ' + strNameSpace + ' baseNode="list" id="dlt_bind" repeatNode="map" useStatusValue="true">';
    strDataList += '<w2:columnInfo>';
    strDataList += '<w2:column dataType="text" id="chk" inputType="text" name="chk"></w2:column>';
    strDataList += '<w2:column dataType="text" id="rdo" inputType="text" name="rdo"></w2:column>';
    strDataList += '</w2:columnInfo>';
    strDataList += '<w2:data use="true">';
    strDataList += '<w2:row><chk>F</chk><rdo>F</rdo></w2:row>';
    strDataList += '<w2:row><chk>F</chk><rdo>F</rdo></w2:row>';
    strDataList += '<w2:row><chk>F</chk><rdo>F</rdo></w2:row>';
    strDataList += '</w2:data>';
    strDataList += '</w2:dataList>';
    // dataList 는 dynamicCreate 미지원 → $p.data.create(strXml) 로 생성
    $p.data.create(strDataList);

    // 조건 설정 - checkboxRadioOnCellClick
    let checkboxRadioOnCellClickText = con_checkboxRadioOnCellClick.getText();
    let checkboxRadioOnCellClickAttr = checkboxRadioOnCellClickText === '' ? '' : 'checkboxRadioOnCellClick="' + checkboxRadioOnCellClickText + '" ';

    // target 생성 (chk Column = checkbox, rdo Column = radio)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + checkboxRadioOnCellClickAttr + 'checkAllType="false" dataList="data:dlt_bind" id="" style="width:500px;height:200px;" ev:oncellclick="scwin.target1_oncellclick" readOnlyBackgroundColor="#D3D3D3">';
    strTarget += '<w2:caption style="" id="caption1" value="checkboxRadioOnCellClick 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="200" inputType="text" id="chk" value="chk (checkbox)"></w2:column>';
    strTarget += '<w2:column width="200" inputType="text" id="rdo" value="rdo (radio)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="200" inputType="checkbox" id="chk"></w2:column>';
    strTarget += '<w2:column width="200" inputType="radio" id="rdo"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // Row 1 readOnly, Row 2 disabled 설정 (chk, rdo Column 모두)
    target1.setCellReadOnly(1, "chk", true);
    target1.setCellReadOnly(1, "rdo", true);
    target1.setCellDisabled(2, "chk", true);
    target1.setCellDisabled(2, "rdo", true);
}



// oncellclick 이벤트 핸들러
//  - 클릭된 Cell 의 row/column/inputType/readOnly/disabled 상태 출력
//  - 상태값 미변경 검증을 위해 클릭 후 cell value 도 함께 출력
scwin.target1_oncellclick = function (rowIndex, columnIndex, columnId) {
    let isReadOnly = target1.getCellReadOnly(rowIndex, columnId);
    let isDisabled = target1.getCellDisabled(rowIndex, columnId);
    let isChecked = target1.getCellChecked(rowIndex, columnId);
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_oncellclick=====");
    wf_body_bottom.getObj("scwin").setReturnValue("rowIndex : " + rowIndex + ", columnIndex : " + columnIndex + ", columnId : " + columnId);
    wf_body_bottom.getObj("scwin").setReturnValue("readOnly : " + isReadOnly + ", disabled : " + isDisabled);
    wf_body_bottom.getObj("scwin").setReturnValue("checked (상태값 미변경 확인) : " + isChecked);
}
